// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // The only admissible caller for success is the owner; the fuzzer can supply any caller.
        // We do NOT vm.assume(caller == owner) because we want to observe both success and revert paths.
        // The rule: If caller is owner, setOwner must not revert and must return true.
        // The bug violates this: with caller==owner, it reverts and never returns true.
        vm.assume(caller == c.owner()); // keep domain wide: owner is the only caller that should succeed
        vm.prank(caller);
        bool ok;
        try c.setOwner(caller) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        // For the reference, caller==owner => ok==true.
        // For the buggy version, the modifier always reverts => ok==false, breaking the property.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address newOwner) public {
        vm.assume(sender != address(0));
        vm.prank(sender);
        try c.setOwner(newOwner) returns (bool success) {
            if (sender == address(this)) {
                assertTrue(success);
                assertEq(c.owner(), newOwner);
            } else {
                assertTrue(false);
            }
        } catch {
            if (sender == address(this)) {
                assertTrue(false);
            }
        }
    }
}
